   435  static void sort_and_uniq(cs_regs arr, uint8_t n, uint8_t *new_n)
   436  {
   437          /* arr is always a tiny (usually n < 3) array,
   438           * a simple O(n^2) sort is efficient enough. */
   439          int i;
   440          int j;
   441          int iMin;
   442          int tmp;
   443
   444          /* a modified selection sort for sorting and making unique */
   445          for (j = 0; j < n; j++) {
   446                  /* arr[iMin] will be min(arr[j .. n-1]) */
   447                  iMin = j;
   448                  for (i = j + 1; i < n; i++) {
   449                          if (arr[i] < arr[iMin])
   450                                  iMin = i;
   451                  }
   452                  if (j != 0 && arr[iMin] == arr[j - 1]) { // duplicate ele found
   453                          arr[iMin] = arr[n - 1];
   454                          --n;
   455                  }
   456                  else {
   457                          tmp = arr[iMin];
   458                          arr[iMin] = arr[j];
   459                          arr[j] = tmp;
   460                  }
   461          }
   462
   463          *new_n = n;
   464  }
   465  void BPF_reg_access(const cs_insn *insn,
   466                  cs_regs regs_read, uint8_t *regs_read_count,
   467                  cs_regs regs_write, uint8_t *regs_write_count)
   468  {
   469          unsigned i;
   470          uint8_t read_count, write_count;
   471          const cs_bpf *bpf = &(insn->detail->bpf);
   472
   473          read_count = insn->detail->regs_read_count;
   474          write_count = insn->detail->regs_write_count;
   475
   476          // implicit registers
   477          memcpy(regs_read, insn->detail->regs_read, read_count * sizeof(insn->detail->regs_read[0]));
   478          memcpy(regs_write, insn->detail->regs_write, write_count * sizeof(insn->detail->regs_write[0]));
   479
   480          for (i = 0; i < bpf->op_count; i++) {
   481                  const cs_bpf_op *op = &(bpf->operands[i]);
   482                  switch (op->type) {
   483                  default:
   484                          break;
   485                  case BPF_OP_REG:
   486                          if (op->access & CS_AC_READ) {
   487                                  regs_read[read_count] = op->reg;
   488                                  read_count++;
   489                          }
   490                          if (op->access & CS_AC_WRITE) {
   491                                  regs_write[write_count] = op->reg;
   492                                  write_count++;
   493                          }
   494                          break;
   495                  case BPF_OP_MEM:
   496                          if (op->mem.base != BPF_REG_INVALID) {
   497                                  regs_read[read_count] = op->mem.base;
   498                                  read_count++;
   499                          }
   500                          break;
   501                  }
   502          }
   503
   504          sort_and_uniq(regs_read, read_count, regs_read_count);
   505          sort_and_uniq(regs_write, write_count, regs_write_count);
   506  }
